script:
frappe.ui.form.on("Entry Pass", {
	refresh(frm) {
		if (frm.is_new() || frm.doc.status !== "Active") {
			return;
		}
		frm.add_custom_button(__("Resend Pass"), function () {
			frappe.confirm(
				__("Re-send Entry Pass {0} to the host and visitor by email, and SMS the pass number to the visitor?", [frm.doc.name]),
				function () {
					frappe.call({
						method: "visitor_pass_tracker.visitor_pass_tracker.doctype.entry_pass.entry_pass.resend_pass",
						args: { entry_pass: frm.doc.name },
						freeze: true,
						freeze_message: __("Sending pass..."),
						callback: function (r) {
							if (!r.message || r.message.status !== "ok") {
								return;
							}
							var lines = [];
							if (r.message.sent && r.message.sent.length) {
								lines.push(__("Sent: {0}", [r.message.sent.join(", ")]));
							}
							if (r.message.skipped && r.message.skipped.length) {
								lines.push(__("No recipient available for: {0}", [r.message.skipped.join(", ")]));
							}
							if (!lines.length) {
								lines.push(__("Nothing to send - the pass has no recipients on file."));
							}
							frappe.msgprint(lines.join("<br>"), __("Resend Pass"));
						}
					});
				}
			);
		});
	}
});
